WITH deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY carrier ORDER BY cost ASC NULLS LAST, id ASC) AS row_num FROM shipments QUALIFY row_num = 1) SELECT s.id, s.order_id, s.carrier, s.shipped_date, s.delivered_date, s.cost, s.row_num, (SELECT MIN(s2.cost) FROM shipments s2 WHERE s2.order_id = s.order_id) AS min_shipment_cost FROM deduped s ORDER BY delivered_date DESC NULLS FIRST
